from pyspark.sql import functions as F

TYPES = ["created", "picked", "departed", "in_transit", "out_for_delivery", "delivered", "exception"]


def solve(shipment_events):
    # The events the load sets aside, unchanged, with the reason in `error`.
    return shipment_events.select("*", F.lit(None).cast("string").alias("error"))
